alter table public.seas
  alter column raster_ordinal set not null,
  alter column danger_level   set not null,
  alter column note           set not null,
  add constraint seas_raster_ordinal_unique unique (raster_ordinal),
  add constraint seas_raster_ordinal_band   check (raster_ordinal between 1 and 255),
  add constraint seas_danger_level_band     check (danger_level between 1 and 5),
  add constraint seas_note_is_a_name        check (length(note) between 3 and 60);

comment on column public.seas.raster_ordinal is 'This sea''s byte value in public.sea_cells. Append-only: data/seas.json array order.';
comment on column public.seas.danger_level is 'Authored WHERE-keyed threat tier, 1 (home waters) to 5 (deadly). READ BY NO RULE TODAY (2026-08-24) — named reader: the by-sea NPC/encounter system, OWNER_REQUESTS row 43. The takes_effect discipline: marked until something reads it.';
comment on column public.seas.note is 'The sea''s character in plain words. READ BY NO RULE TODAY (2026-08-24) — named reader: map labels / the compendium.';

-- ── 2. the raster: 720 rows of 1,440 bytes, one byte per cell ─────────────────────────────────
-- Row r covers latitude (90 - 0.25*(r+1), 90 - 0.25*r]; byte c covers longitude
-- [-180 + 0.25*c, -180 + 0.25*(c+1)). Byte value 0 = not navigable sea here (land, ice, or a
-- landlocked pool no route can reach); 1-255 = public.seas.raster_ordinal.
-- STORAGE SHAPE IS THE POINT (docs/DESIGN_RESEARCH_NAVIGATION.md P.5): one TOASTed bytea costs
-- ~843 ms per detoasting read; 720 inline rows cost 4-8 ms. 1,440 bytes sits under the TOAST
-- threshold and `storage main` states the intent structurally.
create table if not exists public.sea_cells (
  row_idx int   primary key check (row_idx between 0 and 719),
  seas    bytea not null   check (octet_length(seas) = 1440)
);
alter table public.sea_cells alter column seas set storage main;
comment on table public.sea_cells is 'WHICH SEA each 0.25° cell of water belongs to — the spatial key piracy, hazards and NPC levels hang on. Generated by scripts/build-sea-raster.mjs from Natural Earth marine polygons; the water mask itself (channels, ice) is scripts/sea-grid.mjs. One byte per cell = seas.raster_ordinal, 0 = no navigable sea.';

-- Server-private, the 0035 voyage_event_kinds posture: RLS on, NO policy, NO grant. Nothing
-- the client renders comes from here directly; voyage.sea_at is the one door, and a cloud map
-- read would be a world.* + registry + catalog slice of its own.
alter table public.sea_cells enable row level security;

on conflict (row_idx) do nothing;

on conflict (row_idx) do nothing;

on conflict (row_idx) do nothing;

on conflict (row_idx) do nothing;

on conflict (row_idx) do nothing;

on conflict (row_idx) do nothing;

on conflict (row_idx) do nothing;

on conflict (row_idx) do nothing;

on conflict (row_idx) do nothing;

on conflict (row_idx) do nothing;

on conflict (row_idx) do nothing;

on conflict (row_idx) do nothing;

on conflict (row_idx) do nothing;

on conflict (row_idx) do nothing;

on conflict (row_idx) do nothing;

on conflict (row_idx) do nothing;

-- ── 3. the lookup — ONE authority for "which sea is this point in" ────────────────────────────
-- voyage, beside voyage.gc_distance_nm: a geometry read the sea-side rules compose. STRICT on
-- land: null means "not at sea here", it is NEVER a navigability answer (the mover's water
-- raster owns that). Not granted to any client role — no client caller exists; the day a map
-- label wants it, that slice adds a world.* read, a client_rpc_entry_points row and a
-- src/lib/rpc/catalog.ts row TOGETHER (never-ship-half-a-slice).
create or replace function voyage.sea_at(p_lat double precision, p_lon double precision)
returns uuid
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_col int;
  v_ord int;
begin
  if p_lat is null or p_lon is null or p_lat < -90 or p_lat > 90 then
    return null;
  end if;
  v_col := ((floor((p_lon + 180) / 0.25)::int % 1440) + 1440) % 1440;
  select get_byte(c.seas, v_col) into v_ord
    from public.sea_cells c
   where c.row_idx = least(719, greatest(0, floor((90 - p_lat) / 0.25)::int));
  if v_ord is null or v_ord = 0 then return null; end if;
  return (select s.id from public.seas s where s.raster_ordinal = v_ord);
end $$;

comment on function voyage.sea_at(double precision, double precision) is 'WHICH SEA is this point in — total over navigable water, null on land/ice/landlocked pools. The one spatial-membership authority: hazard sampling on a free path, NPC placement by sea, storm placement all compose THIS, never a centroid distance.';

revoke all on function voyage.sea_at(double precision, double precision) from public, anon, authenticated;

-- ── 4. SELF-ASSERT ────────────────────────────────────────────────────────────────────────────
do $$
declare
  v_rows int;
  v_bad  int;
  v_missing text;
  v_expected_disagreements text[] := array[
    'Banda Aceh/Indonesia',
    'Bristol/United Kingdom',
    'Calais/France',
    'Fuzhou/China',
    'Galle/Sri Lanka',
    'Havana/Cuba',
    'Heraklion/Greece',
    'Hirado/Japan',
    'Istanbul/Turkey',
    'Jeju/South Korea',
    'Mangaluru/India',
    'Rhodes/Greece',
    'San Juan/Puerto Rico',
    'Shimonoseki/Japan',
    'Ulsan/South Korea',
    'Bab-el-Mandeb/High seas',
    'Strait of Hormuz/High seas'
  ];
  v_found_disagreements text[];
  v_port record;
  v_ord int;
  v_r0 int; v_c0 int; v_row int; v_col int; v_ring int; v_dr int; v_dc int;
  v_resolved uuid;
  v_probe uuid;
  v_unresolved text;
begin
  -----------------------------------------------------------------------------------------------
  -- (a) SHAPE: 720 rows, every byte value resolves to a sea, every sea has extent somewhere.
  --     Not a bare count: the two set-differences are what make an orphan byte or an extent-less
  --     sea IMPOSSIBLE to ship, whichever direction the drift runs.
  -----------------------------------------------------------------------------------------------
  select count(*) into v_rows from public.sea_cells;
  if v_rows <> 720 then
    raise exception '0040 self-assert FAIL: % raster rows, expected 720', v_rows;
  end if;
  select count(*) into v_bad
    from (select distinct get_byte(c.seas, i.i) as b
            from public.sea_cells c
           cross join generate_series(0, 1439) as i(i)) bytes
   where bytes.b > 0
     and not exists (select 1 from public.seas s where s.raster_ordinal = bytes.b);
  if v_bad > 0 then
    raise exception '0040 self-assert FAIL: % raster byte value(s) name no sea', v_bad;
  end if;
  select string_agg(s.name, ', ' order by s.name) into v_missing
    from public.seas s
   where not exists (
     select 1 from public.sea_cells c
      cross join generate_series(0, 1439) as i(i)
      where get_byte(c.seas, i.i) = s.raster_ordinal);
  if v_missing is not null then
    raise exception '0040 self-assert FAIL: sea(s) with NO extent in the raster: %', v_missing;
  end if;

  -----------------------------------------------------------------------------------------------
  -- (b) EVERY PORT RESOLVES, and the disagreements with the declared sea are EXACTLY the ones
  --     this generation found, by name — a delta against the world as found, not a count. The
  --     ring search mirrors scripts/build-sea-raster.mjs resolveAt() byte for byte.
  -----------------------------------------------------------------------------------------------
  v_found_disagreements := array[]::text[];
  for v_port in
    select p.name || '/' || p.country as key, p.lat, p.lon, p.sea_id
      from public.ports p
     order by p.code
  loop
    v_r0 := least(719, greatest(0, floor((90 - v_port.lat) / 0.25)::int));
    v_c0 := ((floor((v_port.lon + 180) / 0.25)::int % 1440) + 1440) % 1440;
    v_resolved := null;
    <<rings>>
    for v_ring in 0 .. 8 loop
      for v_dr in -v_ring .. v_ring loop
        for v_dc in -v_ring .. v_ring loop
          continue when greatest(abs(v_dr), abs(v_dc)) <> v_ring;
          v_row := v_r0 + v_dr;
          continue when v_row < 0 or v_row > 719;
          v_col := ((v_c0 + v_dc) % 1440 + 1440) % 1440;
          select get_byte(c.seas, v_col) into v_ord from public.sea_cells c where c.row_idx = v_row;
          if v_ord > 0 then
            select s.id into v_resolved from public.seas s where s.raster_ordinal = v_ord;
            exit rings;
          end if;
        end loop;
      end loop;
    end loop;
    if v_resolved is null then
      v_unresolved := coalesce(v_unresolved || ', ', '') || v_port.key;
    elsif v_resolved <> v_port.sea_id then
      v_found_disagreements := v_found_disagreements || v_port.key;
    end if;
  end loop;
  if v_unresolved is not null then
    raise exception '0040 self-assert FAIL: port(s) resolve to NO sea within 8 rings (~120 nm): %', v_unresolved;
  end if;
  if exists (select 1 from unnest(v_found_disagreements) f(k)
              where not (f.k = any(v_expected_disagreements)))
     or exists (select 1 from unnest(v_expected_disagreements) e(k)
              where not (e.k = any(v_found_disagreements))) then
    raise exception '0040 self-assert FAIL: port-vs-cell disagreements drifted. found: [%] expected: [%]',
      array_to_string(v_found_disagreements, ', '), array_to_string(v_expected_disagreements, ', ');
  end if;

  -----------------------------------------------------------------------------------------------
  -- (c) GEOGRAPHY CONTROLS: five real places answer by NAME, and dry land answers nothing.
  --     These assert the Earth, not the seed: mid-North-Atlantic, the Channel off Portsmouth,
  --     mid-Adriatic, the Malacca narrows (water only because a CHANNEL forced it open — so this
  --     also proves channel cells carry a sea), the central Gulf of Mexico, the Sea of Japan —
  --     and the middle of the Sahara, which must be NULL (strict: null is "not at sea", never
  --     a navigability answer).
  -----------------------------------------------------------------------------------------------
  v_probe := voyage.sea_at(35, -40);
  if v_probe is null or v_probe <> (select id from public.seas where name = 'North Atlantic Ocean') then
    raise exception '0040 self-assert FAIL: (35, -40) should be North Atlantic Ocean, got %',
      coalesce((select name from public.seas where id = v_probe), 'NULL');
  end if;
  v_probe := voyage.sea_at(50.5, -1);
  if v_probe is null or v_probe <> (select id from public.seas where name = 'English Channel') then
    raise exception '0040 self-assert FAIL: (50.5, -1) should be English Channel, got %',
      coalesce((select name from public.seas where id = v_probe), 'NULL');
  end if;
  v_probe := voyage.sea_at(42.8, 15);
  if v_probe is null or v_probe <> (select id from public.seas where name = 'Adriatic Sea') then
    raise exception '0040 self-assert FAIL: (42.8, 15) should be Adriatic Sea, got %',
      coalesce((select name from public.seas where id = v_probe), 'NULL');
  end if;
  v_probe := voyage.sea_at(3, 100.4);
  if v_probe is null or v_probe <> (select id from public.seas where name = 'Strait of Malacca') then
    raise exception '0040 self-assert FAIL: (3, 100.4) should be Strait of Malacca, got %',
      coalesce((select name from public.seas where id = v_probe), 'NULL');
  end if;
  v_probe := voyage.sea_at(25, -90);
  if v_probe is null or v_probe <> (select id from public.seas where name = 'Gulf of Mexico') then
    raise exception '0040 self-assert FAIL: (25, -90) should be Gulf of Mexico, got %',
      coalesce((select name from public.seas where id = v_probe), 'NULL');
  end if;
  v_probe := voyage.sea_at(40, 135);
  if v_probe is null or v_probe <> (select id from public.seas where name = 'Sea of Japan') then
    raise exception '0040 self-assert FAIL: (40, 135) should be Sea of Japan, got %',
      coalesce((select name from public.seas where id = v_probe), 'NULL');
  end if;
  if voyage.sea_at(23, 10) is not null then
    raise exception '0040 self-assert FAIL: the middle of the Sahara answered a sea: %',
      (select name from public.seas where id = voyage.sea_at(23, 10));
  end if;

  -----------------------------------------------------------------------------------------------
  -- (d) POSTURE: the read wall did not move.
  -----------------------------------------------------------------------------------------------
  if (select count(*) from public.client_write_grants()) <> 0
     or (select count(*) from public.client_executable_writers()) <> 0
     or (select count(*) from public.client_rpc_entry_points() e where e.fn is null) <> 0
     or (select count(*) from public.caller_evaluated_functions()) <> 0
     or has_function_privilege('anon', 'voyage.sea_at(double precision, double precision)', 'execute')
     or has_function_privilege('authenticated', 'voyage.sea_at(double precision, double precision)', 'execute') then
    raise exception '0040 self-assert FAIL: the read wall moved — a client grant appeared, or sea_at is client-executable';
  end if;

  raise notice '0040 self-assert ok: EVERY WATER ANSWERS ITS SEA — 720 raster rows, every byte names a sea and all 51 seas have extent; all % ports resolve within 8 rings and the % known port-vs-cell disagreements matched by name; six real waters from the Channel to the Sea of Japan answer correctly and the Sahara answers null; danger 1-5 and a plain-words note on every sea (marked: read by no rule yet); sea_cells is server-private and sea_at is not client-executable; 0 client write grants',
    228, 17;
end $$;
